window.__finlexDocLoaded(220,{"id":220,"articles":[{"id":5451,"no":"问1","heading":"问：甲公司委托乙设备生产商建造大型定制专用设备，定制周期超过1年，设备到场后在甲公司安装调试时间不足1年。甲公司需在签署委托合同时点提前向乙公司预付相关款项，为此甲公司借入专门借款。该专门借款利息是否满足《企业会计准则第17号——借款费用》","text":"【发布日期：2026-06-18】\n答：根据借款费用准则第四条和第五条，企业发生的借款费用，可直接归属于符合资本化条件的资产的购建或者生产的，应当予以资本化，计入相关资产成本。借款费用同时满足下列条件的，才能开始资本化：资产支出已经发生，资产支出包括为购建或者生产符合资本化条件的资产而以支付现金、转移非现金资产或者承担带息债务形式发生的支出；借款费用已经发生；为使资产达到预定可使用或者可销售状态所必要的购建或者生产活动已经开始。本问题中，甲公司购建定制化的固定资产，在发生预付账款时，资产支出和借款费用已经发生。甲公司应当结合设备采购的实际情况（如生产商是否已经开始采购设备生产所需原材料、开展设备生产活动等）进一步判断为使资产达到预定可使用或者可销售状态所必要的购建或者生产活动是否已经开始。如果确有证据表明相关购建或者生产活动已经开始，甲公司应当按照借款费用准则规定自生产商相关购建或者生产活动开始时起，至设备达到预定可使用状态为止，将相关借款费用计入资产成本。","seq":0,"links":[{"doc_id":17,"tier":"L1","score":94,"rel_kind":"companion","target_seq":0,"target_art_no":"第一条","dir":"out","note":"核心配套：财政部会计司官方实施问答"},{"doc_id":17,"tier":"L1","score":94,"rel_kind":"companion","target_seq":4,"target_art_no":"第五条","dir":"out","note":"实施问答（问1）：锚定第五条（条文主题匹配）"}]},{"id":5452,"no":"问2","heading":"新矿产资源法下探矿权专门借款费用资本化问题","text":"【发布日期：2026-06-18】\n问：2025年7月1日，新修订的《中华人民共和国矿产资源法》（以下简称新矿产资源法）正式施行，新矿产资源法创设矿业权物权登记制度，实行探矿采矿“直通车”制度，探矿权人探明可供开采的矿产资源后可在探矿权期限内申请将其探矿权转为采矿权（探矿权、采矿权统称为矿业权），在转换时无需就取得采矿权另外支付费用。2025年8月1日，甲煤炭企业（本问题中简称甲公司）以开采煤矿资源为目的，通过公开竞争方式取得某煤矿探矿权。在甲公司取得上述探矿权时点，该煤矿处在详查阶段，储量基本查明。甲公司取得探矿权后，仍需精查矿井建设范围内的地质构造等，估算探明资源量、控制资源量和推断资源量，精准评价开采技术条件并提出防治措施建议，提交满足矿井设计的全套地质资料，编制相关报告，并经监管部门评审和备案后，可取得或将探矿权转为采矿权。甲公司预计需要3至4年完成上述活动并取得采矿权证。为缴纳矿业权初始出让费，甲公司向银行取得专门借款，产生借款费用。甲公司取得的探矿权是否满足《企业会计准则第17号——借款费用》（以下简称借款费用准则）下“符合资本化条件的资产”的定义？如果甲公司在2025年7月1日（新矿产资源法施行日）以前取得探矿权，是否满足借款费用准则下“符合资本化条件的资产”的定义？\n答：根据借款费用准则第四条，企业发生的借款费用，可直接归属于符合资本化条件的资产的购建或者生产的，应当予以资本化，计入相关资产成本；符合资本化条件的资产是指需要经过相当长时间的购建或者生产活动才能达到预定可使用或者可销售状态的固定资产、投资性房地产和存货等资产。在新矿产资源法下，甲公司取得的探矿权与后续形成的采矿权实质上属于一项整体权利，该权利对应的采矿权资产需要经过相当长的购建活动（持续探矿）才能达到其预定可使用状态，甲公司以开采矿产为目的取得探矿权的支出应被视为是最终形成采矿权的过程支出，甲公司相关探矿权满足借款费用准则下“符合资本化条件的资产”的定义。对于在2025年7月1日（新矿产资源法施行日）前企业以开采矿产为目的取得探矿权的情形，如果甲公司在取得探矿权时储量基本查明，且甲公司已确定在探明可供开采的矿产资源后在探矿权期限内可将探矿权转为采矿权，且在转换时无需就取得采矿权另外支付费用，则应视为相关探矿权满足借款费用准则下“符合资本化条件的资产”定义。","seq":1,"links":[{"doc_id":17,"tier":"L1","score":94,"rel_kind":"companion","target_seq":3,"target_art_no":"第四条","dir":"out","note":"实施问答（问2）：锚定第四条（条文主题匹配）"}]},{"id":5453,"no":"问3","heading":"问：用于开发建造房屋建筑物的土地使用权是否满足《企业会计准则第17号——借款费用》（财会〔2006〕3号）关于“符合资本化条件的资产”的定义？","text":"【发布日期：2020-12-11】\n答：根据《企业会计准则第17号——借款费用》（财会〔2006〕3号，以下简称“借款费用准则”），符合资本化条件的资产是指需要经过相当长时间的构建或生产活动才能达到预定可使用或者可销售状态的固定资产、投资性房地产和存货等资产。根据《〈企业会计准则第6号——无形资产〉应用指南》（财会〔2006〕18号，以下简称“无形资产应用指南”）等相关规定，在开发建造房屋建筑物过程中，企业取得的土地使用权应当区别下列情况处理：\n自行开发建造厂房等建筑物，土地使用权与建筑物应当分别进行会计处理，土地使用权的账面价值不与地上建筑物合并计算其成本，而仍作为无形资产进行会计处理。在该情形下，土地使用权在取得时通常已达到预定使用状态，土地使用权不满足借款费用准则规定的“符合资本化条件的资产”定义。因此，根据借款费用准则，企业应当以建造支出（包括土地使用权在房屋建造期间计入在建工程的摊销金额）为基础，而不是以土地使用权支出为基础，确定应予资本化的借款费用金额。\n房地产开发企业，取得的土地使用权用于建造对外出售的房屋建筑物，相关的土地使用权应当计入所建造的房屋建筑物成本。在该情况下，建造的房屋建筑物满足借款费用准则规定的“符合资本化条件的资产”定义。因此，根据借款费用准则，企业应当以包括土地使用权支出的建造成本为基础，确定应予资本化的借款费用金额。","seq":2,"links":[{"doc_id":17,"tier":"L1","score":94,"rel_kind":"companion","target_seq":3,"target_art_no":"第四条","dir":"out","note":"实施问答（问3）：锚定第四条（条文主题匹配）"},{"doc_id":7,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第06号——无形资产》"}]}]});
